// Compiles design.tokens.json (DTCG) into CSS custom properties + the Tailwind 4 theme.
// Output: src/styles/generated/tokens.css (not committed; regenerated by predev/prebuild/pretest).
import StyleDictionary from 'style-dictionary';

const OUT = 'src/styles/generated/';

function fmtNumber(n) {
  return Number(n.toFixed(4)).toString();
}

function cssValue(token) {
  const value = token.$value ?? token.value;
  const type = token.$type ?? token.type;
  if (type === 'color') {
    if (value.colorSpace !== 'oklch') throw new Error(`${token.name}: colours must be authored in OKLCH`);
    const [l, c, h] = value.components;
    const alpha = value.alpha !== undefined && value.alpha !== 1 ? ` / ${fmtNumber(value.alpha)}` : '';
    return `oklch(${fmtNumber(l * 100)}% ${fmtNumber(c)} ${fmtNumber(h)}${alpha})`;
  }
  if (type === 'dimension') return `${value.value}${value.unit}`;
  if (type === 'fontFamily') {
    const list = Array.isArray(value) ? value : [value];
    return list.map((f) => (/[\s]/.test(f) ? `"${f}"` : f)).join(', ');
  }
  throw new Error(`${token.name}: unsupported token type ${type}`);
}

// path → CSS variable name, e.g. color.light.accent-soft → --atx-color-accent-soft
function varName(token) {
  const path = token.path.filter((p) => p !== 'light' && p !== 'dark');
  return `--atx-${path.join('-')}`;
}

StyleDictionary.registerFormat({
  name: 'atx/css',
  format: ({ dictionary }) => {
    const tokens = dictionary.allTokens;
    const light = tokens.filter((t) => t.path[1] !== 'dark');
    const dark = tokens.filter((t) => t.path[0] === 'color' && t.path[1] === 'dark');
    const decl = (list, indent) => list.map((t) => `${indent}${varName(t)}: ${cssValue(t)};`).join('\n');
    const themeLines = tokens
      .filter((t) => t.path[1] !== 'dark')
      .map((t) => {
        const name = varName(t).replace('--atx-', '');
        if (t.path[0] === 'color') return `  --color-${t.path.slice(2).join('-')}: var(${varName(t)});`;
        if (t.path[0] === 'font') return `  --font-${t.path.slice(2).join('-')}: var(${varName(t)});`;
        if (t.path[0] === 'radius') return `  --radius-${t.path.slice(1).join('-')}: var(${varName(t)});`;
        if (t.path[0] === 'size') return `  --spacing-${t.path.slice(1).join('-')}: var(${varName(t)});`;
        return `  --${name}: var(${varName(t)});`;
      });
    return `/* Generated from design.tokens.json — do not edit by hand. */
:root {
${decl(light, '  ')}
  color-scheme: light;
}
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
${decl(dark, '    ')}
    color-scheme: dark;
  }
}
:root[data-theme="dark"] {
${decl(dark, '  ')}
  color-scheme: dark;
}
/* Tailwind theme: only token colours exist (the default palette is removed). */
@theme inline {
  --color-*: initial;
${themeLines.join('\n')}
}
`;
  },
});

const sd = new StyleDictionary({
  source: ['design.tokens.json'],
  usesDtcg: true,
  log: { verbosity: 'silent', warnings: 'disabled' },
  platforms: {
    css: { buildPath: OUT, files: [{ destination: 'tokens.css', format: 'atx/css' }] },
  },
});

await sd.buildAllPlatforms();
